(function(){try{var e=typeof window<"u"?window:typeof global<"u"?global:typeof globalThis<"u"?globalThis:typeof self<"u"?self:{},s=new e.Error().stack;s&&(e._sentryDebugIds=e._sentryDebugIds||{},e._sentryDebugIds[s]="3acddcfd-7adb-407c-adef-50f407896673",e._sentryDebugIdIdentifier="sentry-dbid-3acddcfd-7adb-407c-adef-50f407896673")}catch{}})();var t="Code de conduite de la communauté",r={p1:"Nous aimons tous la musique! Comme toute communauté, nous avons un code de conduite pour préserver l’harmonie et une bonne ambiance, et pour que chacun se sente à l’aise ici. Créons un environnement accueillant qui nous inspire à créer."},u={p1:"Principes de cohabitation :",p2:"Respect",p3:"Esprit d’ensemble",p4:"Équité"},o={p1:"Comportements attendus :",p2:"Traitez tous les membres avec respect.",p3:"La rétroaction constructive est la bienvenue.",p4:"Tout tourne autour de la musique ; veillons à ce que nos commentaires et notre contenu ne portent que sur la musique.",p5:"Traitez les autres comme vous aimeriez qu’on vous traite."},n={p1:"Comportements inacceptables (nous pouvons supprimer votre compte sans préavis) :",p2:"Traiter les autres créateurs de manière irrespectueuse ou offensante.",p3:"Pollupostage.",p4:"Diffuser du contenu à caractère sexuel.",p5:"Formuler des commentaires visant à rabaisser, offenser ou importuner un membre de la communauté."},i={p1:"Actions publiques :"},a={p1:"Motifs de bannissement immédiat :",p2:"Partager tout contenu à caractère sexuel (images, commentaires, etc.).",p3:"Partager du contenu ou publier des commentaires qui encouragent la violence, le racisme, la xénophobie, l’homophobie, le sexisme, etc.",p4:"Envoyer du pourriel aux autres."},p={p1:"Autres types de comportements inacceptables :",p2:"Insulter ou publier des commentaires méprisants à l’égard de tout membre de la communauté :",p3:"1re fois : nous désactiverons la possibilité de commenter jusqu’à nouvel ordre.",p4:"2e fois : nous désactiverons définitivement la possibilité de commenter ou supprimerons votre compte.",p5:"Envoi de pourriels au service d’assistance :",p6:"Notre équipe de soutien sera toujours heureuse de vous aider, pourvu que vous nous écriviez avec respect et exclusivement au sujet de notre plateforme. Les attitudes irrespectueuses ou assimilables à du pourriel ne sont pas les bienvenues et peuvent entraîner la suppression de votre compte."},c={p1:"Qu’est-ce qu’un commentaire irrespectueux ?",p2:"Ce type de commentaire est généralement hors sujet, inapproprié, nuisible ou simplement agaçant. Il n’est pas écrit avec bienveillance et vise à mettre l’autre personne mal à l’aise ou à l’humilier.",p3:"Si vous n’êtes pas certain que votre commentaire soit irrespectueux ou non, évitez de le publier et trouvez une manière respectueuse et civilisée de vous exprimer."},l={title:t,s1:r,s2:u,s3:o,s4:n,s5:i,s6:a,s7:p,s8:c};export{l as default,r as s1,u as s2,o as s3,n as s4,i as s5,a as s6,p as s7,c as s8,t as title};

